contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept two parameters: amount to deposit and a flag whether to attempt withdraw.
    // The function is payable so the caller can fund this contract before calling run.
    function run(uint256 depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount);

        // initial observed balance mapping for this test contract (before deposit)
        uint256 beforeRecorded = c.balances(address(this));
        uint256 beforeCBal = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // Deposit by invoking fallback with Ether
        c.f{value: depositAmount}();

        // observed after deposit
        uint256 afterRecorded = c.balances(address(this));
        uint256 afterCBal = address(c).balance;
        uint256 afterThis = address(this).balance;

        // deposit must increase contract's recorded balance for this contract by exactly depositAmount
        // and increase c's ether balance by depositAmount, and decrease this contract balance by depositAmount
        assert(afterRecorded == beforeRecorded + depositAmount);
        assert(afterCBal == beforeCBal + depositAmount);
        assert(afterThis == beforeThis - depositAmount);

        bool didRevert = false;
        if (doWithdraw) {
            // attempt withdraw and capture whether it reverts
            try c.withdraw() {
                didRevert = false;
            } catch {
                didRevert = true;
            }

            // After withdraw: if it did NOT revert, recorded balance for this contract must be zero
            // and c's balance must have decreased by the amount that was recorded before withdraw
            uint256 recordedAfterWithdraw = c.balances(address(this));
            uint256 cBalAfter = address(c).balance;

            if (!didRevert) {
                assert(recordedAfterWithdraw == 0);
                // c's balance should be <= previous afterCBal (it decreased by at least the withdrawn amount)
                // More precisely, since withdraw sends exactly the recorded amount and then sets it to zero,
                // cBalAfter == afterCBal - afterRecorded
                assert(cBalAfter == afterCBal - afterRecorded);
            } else {
                // If it reverted, the recorded balance must be unchanged
                assert(recordedAfterWithdraw == afterRecorded);
            }
        }
    }

    // accept Ether so this contract can fund deposits and receive withdrawals
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmount: how much Ether to send into C's fallback
    // doWithdraw: whether to attempt a withdraw after deposit
    function run(uint256 depositAmount, bool doWithdraw) public payable {
        // ensure this test contract has enough Ether to fund the deposit
        require(address(this).balance >= depositAmount);

        // observe before-state
        uint256 beforeRecorded = c.balances(address(this));
        uint256 beforeCBal = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // perform deposit by calling C's fallback (send Ether to c)
        // note: calling payable fallback is done by calling address(c).call with empty data
        (bool sentDeposit, ) = address(c).call{value: depositAmount}("");
        require(sentDeposit);

        // observe after deposit
        uint256 afterRecorded = c.balances(address(this));
        uint256 afterCBal = address(c).balance;
        uint256 afterThis = address(this).balance;

        // deposit must increase mapping and C's balance by exactly depositAmount, and decrease this balance
        assert(afterRecorded == beforeRecorded + depositAmount);
        assert(afterCBal == beforeCBal + depositAmount);
        assert(afterThis == beforeThis - depositAmount);

        // attempt withdraw if requested, capturing revert status
        bool didRevert;
        if (doWithdraw) {
            try c.withdraw() {
                didRevert = false;
            } catch {
                didRevert = true;
            }

            uint256 recordedAfterWithdraw = c.balances(address(this));
            uint256 cBalAfter = address(c).balance;

            if (!didRevert) {
                // if withdraw succeeded, recorded balance must be zero
                // and c's balance must have decreased by the amount that was recorded just after deposit
                assert(recordedAfterWithdraw == 0);
                assert(cBalAfter == afterCBal - afterRecorded);
            } else {
                // if withdraw reverted, recorded balance must be unchanged
                assert(recordedAfterWithdraw == afterRecorded);
            }
        }
    }

    // accept Ether so this contract can fund deposits and receive withdrawals
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmount: amount to send to C's fallback
    // doWithdraw: whether to call withdraw after deposit
    function run(uint256 depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount);

        // observe before-state
        uint256 beforeRecorded = c.balances(address(this));
        uint256 beforeCBal = address(c).balance;

        // perform deposit by calling C's fallback
        (bool sentDeposit, ) = address(c).call{value: depositAmount}("");
        require(sentDeposit);

        // observe after deposit
        uint256 afterRecorded = c.balances(address(this));
        uint256 afterCBal = address(c).balance;

        // perform withdraw attempt if requested and capture revert status
        bool didRevert;
        try c.withdraw() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // observe final state
        uint256 finalRecorded = c.balances(address(this));
        uint256 finalCBal = address(c).balance;

        // Single assert encoding the conditional properties:
        // If withdraw was attempted (doWithdraw==true) and did not revert:
        //   finalRecorded == 0 && finalCBal == afterCBal - afterRecorded
        // If withdraw was attempted and reverted:
        //   finalRecorded == afterRecorded && finalCBal == afterCBal
        // If withdraw was not attempted (doWithdraw==false): state remains as after deposit
        //   finalRecorded == afterRecorded && finalCBal == afterCBal
        assert(
            (!doWithdraw && finalRecorded == afterRecorded && finalCBal == afterCBal)
            || (doWithdraw && !didRevert && finalRecorded == 0 && finalCBal == afterCBal - afterRecorded)
            || (doWithdraw && didRevert && finalRecorded == afterRecorded && finalCBal == afterCBal)
        );
    }

    receive() external payable {}
}

