contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes an amount to deposit (so we can set up a nonzero balance) and a flag
    // indicating whether to attempt withdrawal. We make one deposit from this contract
    // to c by invoking its fallback (payable) so that balances[this] increases.
    function run(uint256 depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount);

        // initial reported balance for this test-contract (before any deposit)
        uint256 beforeReported = c.balances(address(this));
        // initial contract ether balance
        uint256 beforeContractBal = address(c).balance;

        // perform deposit to increase the contract's recorded balance for this address
        if (depositAmount > 0) {
            // call fallback by sending ether with empty calldata
            // must be a top-level state-changing call
            c.call{value: depositAmount}("");
        }

        // read reported balance after deposit
        uint256 midReported = c.balances(address(this));
        uint256 midContractBal = address(c).balance;

        // Now attempt withdraw if requested. Capture whether it reverted.
        bool didRevert;
        if (doWithdraw) {
            try c.withdraw() {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        } else {
            didRevert = false;
        }

        // read reported balance and contract balance after withdraw attempt
        uint256 afterReported = c.balances(address(this));
        uint256 afterContractBal = address(c).balance;

        // Let reportedBeforeWithdraw be the balance reported just before withdraw attempt
        uint256 reportedBeforeWithdraw = midReported;

        // General rule asserted:
        // If withdraw was attempted and did not revert, then the contract's reported balance
        // for this address must become zero and the contract's ether balance must have
        // decreased by exactly reportedBeforeWithdraw. If withdraw reverted or was not
        // attempted, no constraint is required (the assert still must be a general rule),
        // so we assert the implication.
        assert(!doWithdraw || didRevert || (afterReported == 0 && midContractBal >= reportedBeforeWithdraw && afterContractBal + reportedBeforeWithdraw == midContractBal));
    }

    // allow receiving ETH for the test runner
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Deposit an amount into c (via fallback) and optionally attempt withdraw.
    // We require this contract hold enough Ether to deposit the requested amount.
    function run(uint256 depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount);

        // read reported balance before any deposit
        uint256 beforeReported = c.balances(address(this));
        uint256 beforeContractBal = address(c).balance;

        // perform deposit by sending ETH to c's fallback
        if (depositAmount > 0) {
            // must use address(c).call to invoke fallback payable
            (bool sent, ) = address(c).call{value: depositAmount}("");
            require(sent);
        }

        // reported balance and contract balance immediately before withdraw attempt
        uint256 reportedBeforeWithdraw = c.balances(address(this));
        uint256 contractBalBeforeWithdraw = address(c).balance;

        bool didRevert = false;
        if (doWithdraw) {
            try c.withdraw() {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        }

        uint256 reportedAfter = c.balances(address(this));
        uint256 contractBalAfter = address(c).balance;

        // General rule:
        // If we attempted withdraw and it did NOT revert, then (1) the reported balance
        // for this test contract must be zero afterwards, and (2) the contract's Ether
        // balance must have decreased by at least the amount that was reported for this
        // test contract immediately before the withdraw. We use >= to allow for the
        // possibility of other state changes (conservative check) but assert that the
        // decrease is at least the reported amount.
        assert(!doWithdraw || didRevert || (reportedAfter == 0 && contractBalBeforeWithdraw >= reportedBeforeWithdraw && contractBalBeforeWithdraw - contractBalAfter >= reportedBeforeWithdraw));
    }

    // allow receiving ETH for funding deposits or receiving withdrawn ETH
    receive() external payable {}
}

